$u=require_role('student');$err='';
$q=db()->prepare('SELECT u.email,u.email_verified_at,f.name faculty,d.name department,p.name programme FROM users u LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN faculties f ON f.id=d.faculty_id LEFT JOIN programmes p ON p.id=u.programme_id WHERE u.id=?');$q->execute([$u['id']]);$academic=$q->fetch()?:[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$first=post_string('first_name',80);$last=post_string('last_name',80);$email=strtolower(post_string('email',190));$phone=post_string('phone',30);
 if(!$first||!$last||!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Enter your first name, last name, and a valid email address.';
 else{$check=db()->prepare('SELECT id FROM users WHERE email=? AND id<>?');$check->execute([$email,$u['id']]);if($check->fetchColumn())$err='That email address is already in use.';else{
  $emailChanged=strtolower((string)($academic['email']??''))!==$email;
  db()->prepare('UPDATE users SET first_name=?,last_name=?,email=?,email_verified_at=IF(?,NULL,email_verified_at),phone=?,profile_complete=1 WHERE id=?')->execute([$first,$last,$email,$emailChanged?1:0,$phone?:null,$u['id']]);
  $_SESSION['user']['first_name']=$first;$_SESSION['user']['last_name']=$last;$_SESSION['user']['email']=$email;$_SESSION['user']['phone']=$phone;$_SESSION['user']['profile_complete']=1;if($emailChanged)$_SESSION['user']['email_verified_at']=null;
  audit('profile_completed','user',(int)$u['id'],'Student completed their contact profile');$needsVerification=$emailChanged||empty($academic['email_verified_at']);$mailSent=$needsVerification?issue_email_verification((int)$u['id'],$email,trim($first.' '.$last)):true;flash('success','Your profile is complete.');if($needsVerification)flash($mailSent?'info':'warning',$mailSent?'A verification link was sent to your email address.':'Email verification could not be sent. The system administrator needs to configure SMTP email.');redirect('student/dashboard.php');
 }}
}
$q=db()->prepare('SELECT u.first_name,u.last_name,u.email,u.email_verified_at,u.phone,u.matric_number,f.name faculty,d.name department,p.name programme,s.supervisor_id,su.first_name supervisor_first,su.last_name supervisor_last FROM users u LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN faculties f ON f.id=d.faculty_id LEFT JOIN programmes p ON p.id=u.programme_id LEFT JOIN student_supervisors s ON s.student_id=u.id AND s.ended_at IS NULL LEFT JOIN users su ON su.id=s.supervisor_id WHERE u.id=? ORDER BY s.assigned_at DESC LIMIT 1');$q->execute([$u['id']]);$profile=$q->fetch();
$pageTitle='My Academic Profile';$crumbTrail=['Profile'];require dirname(__DIR__).'/includes/header.php';
?>
<?php $fullName=trim(($profile['first_name']??'').' '.($profile['last_name']??'')); $sq=db()->prepare('SELECT CONCAT_WS(" ",su.first_name,su.last_name) FROM project_supervisors ps JOIN users su ON su.id=ps.supervisor_id JOIN project_members pm ON pm.project_id=ps.project_id WHERE pm.student_id=? AND ps.ended_at IS NULL ORDER BY ps.assigned_at DESC LIMIT 1');$sq->execute([$u['id']]);$supName=(string)$sq->fetchColumn(); $pq=db()->prepare('SELECT p.title,p.status FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.student_id=? ORDER BY p.created_at DESC LIMIT 1');$pq->execute([$u['id']]);$myProject=$pq->fetch();$curStep=null;if($myProject){$pq2=db()->prepare('SELECT id FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.student_id=? ORDER BY p.created_at DESC LIMIT 1');$pq2->execute([$u['id']]);$myPid=(int)$pq2->fetchColumn();$curStep=ui_current_milestone(ui_student_milestones($myPid,(string)$myProject['status']));} ?>
