    <div class="row g-3"><div class="col-md-6"><label class="field-label" for="first_name">First name</label><input class="form-control" id="first_name" name="first_name" maxlength="80" required value="<?= e($profile['first_name']) ?>"></div><div class="col-md-6"><label class="field-label" for="last_name">Last name</label><input class="form-control" id="last_name" name="last_name" maxlength="80" required value="<?= e($profile['last_name']) ?>"></div><div class="col-12"><label class="field-label" for="email">Registered student email</label><input class="form-control" id="email" name="email" type="email" maxlength="190" required value="<?= e($profile['email']) ?>"></div><div class="col-12"><label class="field-label" for="phone">Contact phone number</label><input class="form-control" id="phone" name="phone" maxlength="30" value="<?= e($profile['phone']) ?>"></div></div>
