<div class="col-lg-6"><section class="card p-4 h-100"><h2 class="card-title-icon"><?= ui_icon('book',18) ?>Academic Affiliation</h2>
  <dl class="data-list"><dt>Faculty / School</dt><dd><?= e($profile['faculty']??'Not assigned') ?></dd><dt>Academic Department</dt><dd><?= e($profile['department']??'Not assigned') ?></dd><dt>Programme</dt><dd><?= e($profile['programme']??'Not assigned') ?></dd><dt>University Matriculation No</dt><dd><?= e($profile['matric_number']) ?></dd></dl></section></div></div>
